const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=v=>v?.[0];
const variant=v=>Object.keys(v||{})[0];
const labels={unknown:'Unclear',subscription:'Software subscription',oneTime:'Software one-time purchase',other:'Other expense',pending:'Needs review',linked:'Assigned',ignored:'Ignored'};
const when=n=>Number(n)>0?new Date(Number(n)/1e6).toLocaleString():'Not yet';
export function paymentMoney(n,currency){try{return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(Number(n)/10**new Intl.NumberFormat(undefined,{style:'currency',currency}).resolvedOptions().maximumFractionDigits);}catch{return `${n} minor units ${currency}`;}}
const button=(id,text,primary=false)=>`<button type="button" id="${id}" class="pill ${primary?'primary':'outline'}">${text}</button>`;
const fieldLabels={title:'Title',vendor:'Vendor',product:'Software / plan',interval:'Billing frequency',amountMinor:'Price in minor units',currency:'Currency',taxBasis:'Tax basis',start:'Contract start',end:'Contract end',renewalRule:'Renewal rule',renewalDate:'Next renewal',noticeDays:'Notice in days',noticeMonths:'Notice in months',seats:'License count',note:'Contract note'};
const choices={interval:[['month','Monthly'],['quarter','Quarterly'],['year','Yearly'],['once','One-time'],['other','Usage-based / other']],renewalRule:[['auto','Automatic'],['manual','Manual'],['none','No renewal'],['indefinite','No fixed expiry']],taxBasis:[['gross','Including tax'],['net','Excluding tax'],['unknown','Unknown']]};
const questions={product:'Which software or plan did you buy?',interval:'How is it billed?',amountMinor:'What total price is agreed per billing period? A card charge may include tax, credits or several products.',currency:'Which currency is the contract priced in?',taxBasis:'Does the contract price include tax?',start:'When did the contract start?',end:'When does the current contract period end?',renewalRule:'How does the contract renew?',renewalDate:'When is the next renewal?',noticeDays:'How many days of cancellation notice are required?',noticeMonths:'How many calendar months of cancellation notice are required?',seats:'How many licenses are included?',title:'What should this contract be called?',vendor:'Who is the contractual vendor?',note:'What else should be recorded?'};
export async function renderBrex(root,ctx,page='review',id=null){
 const {api,token,stale,space}=ctx;
 root.innerHTML='<p role="status">Opening payment review…</p>';
 const renderId=Symbol('brex');root.brexRender=renderId;
 const current=()=>!stale()&&root.brexRender===renderId;
 const message=(text,bad=false)=>{const node=root.querySelector('[data-message]');if(node){node.textContent=text;node.classList.toggle('error',bad);}};
 const run=(el,fn,disabled=()=>false)=>{let running=false;el?.addEventListener('click',async()=>{if(running||!current())return;running=true;el.disabled=true;try{await fn();}catch{if(current())message('The result could not be confirmed. Refresh before retrying; your saved data is retained.',true);}finally{running=false;if(current())el.disabled=disabled();}});};
 const reload=()=>renderBrex(root,ctx,page,id);
 let status;try{status=opt(await api.brexStatus(token));}catch{if(current())root.innerHTML='<p role="alert">Payment review is unavailable. Reopen Contracts and retry.</p>';return;}
 if(!current())return;
 if(!status){root.innerHTML='<section class="scard"><h2>Payment review</h2><p>Only the owner of this personal space, teamspace owners and app admins can manage payment data. Archived spaces are read-only. Reopen Contracts if your session expired.</p></section>';return;}
 const heading=(title,detail)=>`<header class="saas-heading"><div><span class="eyebrow">${esc(space.name)} / PAYMENTS</span><h2>${title}</h2><p>${detail}</p></div><a class="pill outline" href="${page==='settings'?'#/payments':'#/settings/brex'}">${page==='settings'?'Payment review':'Brex settings'}</a></header><p data-message role="status" aria-live="polite"></p>`;
 if(page==='settings'){
  root.innerHTML=heading('Connect Brex','Choose the cards whose payments belong in this space.')+`<div class="brex-columns"><section class="scard"><h3>1. Connect and test</h3><p>Create a Brex API token with <strong>Cards: Read</strong> and <strong>Card transactions: Read</strong>. Contracts only reads Brex; it cannot pay or change cards.</p><p><a href="https://developer.brex.com/guides/authentication" target="_blank" rel="noopener noreferrer">Brex token setup ↗</a> · <a href="brex-guide.md" target="_blank" rel="noopener">Contracts setup guide</a></p><p class="spacehelp">The token is stored on your organisation’s Cloud Engine. Hosting operators, controllers and backups remain inside the trust boundary. It is never returned to this screen or sent to AI. Use a dedicated token with read permissions only.</p><label for="brex-token">Brex API token ${status.configured?'(enter only to replace)':''}</label><input id="brex-token" type="password" autocomplete="new-password" maxlength="2048"><div class="btnrow">${button('brex-save','Save token')}${button('brex-test','Test connection',true)}</div><p>Connection: ${status.testedAt>0n?'Read access tested '+esc(when(status.testedAt)):status.configured?'Token saved; not yet tested':'Not connected'}</p><p class="spacehelp">A successful test confirms reads work. It does not prove the token has no additional Brex permissions.</p></section><section class="scard"><h3>2. Select cards and start review</h3><p>The initial scan starts on <strong>${esc(status.since||`${new Date().getFullYear()-1}-01-01`)}</strong>. Afterwards, Contracts reconciles this range once every 24 hours, including delayed bookings. Only selected cards are retained.</p><label for="brex-card-search">Find a card</label><input id="brex-card-search" type="search" placeholder="Name or last four digits"><fieldset class="brex-cards"><legend>Cards visible to this Brex token</legend>${status.cards.length?status.cards.map(c=>`<label data-card-text="${esc((c.name+' '+c.lastFour).toLowerCase())}"><input name="brex-card" type="checkbox" value="${esc(c.id)}" ${status.selected.includes(c.id)?'checked':''}><span>${esc(c.name||'Unnamed card')} · •••• ${esc(c.lastFour)}<small>${esc(c.status)}</small></span></label>`).join(''):'<p>Test the connection to load cards.</p>'}</fieldset>${status.moreCards?button('brex-more-cards','Load more cards'):''}<label class="brex-check"><input id="brex-ai" type="checkbox" ${status.aiEnabled?'checked':''}>Use the configured Hub AI for software recognition</label><p class="spacehelp">When enabled, merchant names, payment samples and up to 200 contract titles/vendors from this space go to the configured AI provider. All imported expenses remain available even if AI is unavailable.</p><label class="brex-check"><input id="brex-daily" type="checkbox" ${status.enabled?'checked':''}>Import now and check daily</label><div class="btnrow">${button('brex-configure','Save cards and schedule',true)}</div></section></div><section class="scard"><h3>Import status</h3><dl class="brex-facts"><dt>State</dt><dd>${status.scanning?'Import in progress':status.enabled?'Daily import enabled':'Paused'}</dd><dt>Last completed import</dt><dd>${esc(when(status.lastSuccess))}</dd><dt>Next page / check</dt><dd>${esc(when(status.nextAt))}</dd><dt>Stored payments</dt><dd>${status.payments}</dd><dt>Pages processed</dt><dd>${status.pages}</dd></dl>${status.error?`<p role="alert">${esc(status.error)}</p>`:''}<div class="btnrow">${button('brex-refresh','Refresh status')}${button('brex-sync','Run due import')}${button('brex-disconnect','Disconnect Brex')}</div><details><summary>Disconnect and retained data</summary><p>Disconnect stops imports and removes the saved token. Imported payments, assignments and reviews remain in this space, including existing backups. Revoke the dedicated token in Brex if it should no longer work anywhere.</p></details></section>`;
  root.querySelector('#brex-card-search').oninput=e=>{for(const row of root.querySelectorAll('[data-card-text]'))row.hidden=!row.dataset.cardText.includes(e.target.value.toLowerCase());};
  run(root.querySelector('#brex-save'),async()=>{const input=root.querySelector('#brex-token');const key=input.value;input.value='';const r=await api.saveBrexToken(token,key);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-test'),async()=>{message('Testing card and transaction reads…');const r=await api.testBrexConnection(token);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-more-cards'),async()=>{const r=await api.moreBrexCards(token);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-configure'),async()=>{const selected=[...root.querySelectorAll('[name=brex-card]:checked')].map(n=>n.value);const r=await api.configureBrex(token,selected,root.querySelector('#brex-daily').checked,root.querySelector('#brex-ai').checked);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-disconnect'),async()=>{if(!confirm('Disconnect Brex in this space and remove its saved token? Existing payment evidence remains.'))return;const r=await api.disconnectBrex(token);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-sync'),async()=>{const r=await api.syncBrex(token);if(current()){await reload();message(r.detail,!r.ok);}});
  run(root.querySelector('#brex-refresh'),reload);return;
 }
 if(page==='guide'){await guide(BigInt(id));return;}
 if(id!=null){await detail(BigInt(id));return;}
 root.innerHTML=heading('Payment review','Review software purchases where money was actually charged. Assignments do not overwrite contract terms.')+`<section class="scard"><p>${status.payments} payments · ${status.groups} merchant/card/currency groups · Last complete import: ${esc(when(status.lastSuccess))}</p>${status.error?`<p role="alert">${esc(status.error)}</p>`:''}${status.scanning?'<p role="status">Import is in progress. This list is partial until the import completes.</p>':''}<div class="brex-toolbar"><label for="brex-filter">Show</label><select id="brex-filter"><option value="pending">Needs review</option><option value="all">All payments</option><option value="linked">Assigned</option><option value="ignored">Ignored</option></select>${button('brex-reload','Refresh list')}</div><div id="brex-list"></div><div class="btnrow">${button('brex-prev','Previous')}${button('brex-next','Next')}</div></section>`;
 let offset=0n,next=[],sequence=0;
 async function load(){const seq=++sequence;const r=opt(await api.listBrexReview(token,root.querySelector('#brex-filter').value,offset,30n));if(!current()||seq!==sequence)return;if(!r){message('Access is unavailable. Reopen Contracts.',true);return;}next=r.next;
  root.querySelector('#brex-list').innerHTML=r.rows.length?`<p>${r.total} groups in this view</p><div class="saas-table-scroll"><table class="saas-table"><thead><tr><th>Merchant</th><th>Payments</th><th>Latest charge</th><th>Recognition</th><th>Review</th></tr></thead><tbody>${r.rows.map(g=>`<tr><td><a href="#/payments/${g.id}">${esc(g.merchant||g.descriptor||'Unnamed merchant')}</a><small>${esc(status.cards.find(c=>c.id===g.cardId)?.name||'Selected card')}</small></td><td>${g.count}<small>${esc(g.latestDate)}</small></td><td>${esc(paymentMoney(g.latestAmount,g.currency))}</td><td>${labels[variant(g.classification)]}<small>${esc(g.aiError||g.reason)}</small></td><td>${g.summary?.split?'Individual assignments':labels[variant(g.state)]}${g.summary?`<small>${g.summary.pending} need review · ${g.summary.linked} assigned · ${g.summary.ignored} ignored</small>`:''}${g.candidates.length?`<small>${g.candidates.length} possible contract(s)</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="saas-empty"><h3>No payments in this view</h3><p>'+(!status.configured?'Connect Brex to start.':status.scanning?'The import is still running. Refresh to see new payments.':'Try All payments, or check the connection and selected cards.')+'</p></div>';
  root.querySelector('#brex-prev').disabled=offset===0n;root.querySelector('#brex-next').disabled=!next.length;
 }
 run(root.querySelector('#brex-reload'),load);run(root.querySelector('#brex-next'),async()=>{if(!next.length)return;offset=next[0];await load();},()=>!next.length);run(root.querySelector('#brex-prev'),async()=>{offset=offset>=30n?offset-30n:0n;await load();},()=>offset===0n);root.querySelector('#brex-filter').onchange=()=>{offset=0n;load().catch(()=>message('Could not load this view.',true));};await load();
 async function detail(gid){
  const d=opt(await api.brexReviewDetail(token,gid,0n));if(!current())return;if(!d){root.innerHTML='<p role="alert">This review is unavailable in this space.</p>';return;}
  const g=d.group,linked=g.summary?.split?null:opt(g.state.linked==null?[]:[g.state.linked]);
  root.innerHTML=heading(esc(g.merchant||'Payment review'),'Compare the evidence, then decide where these payments belong.')+`<p><a href="#/payments">← Payment review</a></p><div class="brex-columns"><section class="scard"><h3>Payment evidence</h3><p>${g.count} payments · Net booked movement ${esc(paymentMoney(g.totalMinor,g.currency))}</p><p>${esc(g.reason)}</p>${g.aiError?`<p role="alert">${esc(g.aiError)}</p>`:''}<p class="spacehelp">Recognition is a suggestion. One charge may cover multiple products, taxes or credits. Contract dates and notice periods need separate evidence.</p>${button('brex-analyze','Ask AI to review')}<div id="brex-evidence" class="saas-table-scroll"></div>${button('brex-more-payments','More payments')}<p id="brex-selected" role="status">0 payments selected</p><p class="spacehelp">Select individual payments, then choose a contract on the right. Each payment keeps its own assignment and history.</p></section><section class="scard"><h3>Assign or create</h3><p>Current state: <strong>${g.summary?.split?'Individual assignments':labels[variant(g.state)]}</strong>${linked!=null?` · <a href="#/c/${linked}">Open linked contract</a>`:''}</p><label for="brex-kind">What is this purchase?</label><select id="brex-kind">${Object.entries(labels).filter(([k])=>['unknown','subscription','oneTime','other'].includes(k)).map(([k,v])=>`<option value="${k}" ${variant(g.classification)===k?'selected':''}>${v}</option>`).join('')}</select><label for="brex-target-search">Find an existing contract</label><input id="brex-target-search" type="search" placeholder="Vendor, software or contract title"><p class="spacehelp">Up to 200 matches are shown. Search to narrow larger portfolios.</p><label for="brex-target">Existing contract</label><select id="brex-target"><option value="">Choose a contract</option></select><div id="brex-existing"></div><label class="brex-check"><input id="brex-auto" type="checkbox" ${g.autoLink?'checked':''}>Automatically attach future payments with this exact card, merchant, currency and amount</label><p class="spacehelp">Changed amounts, refunds and unavailable contracts return for review. Confirmed terms never change automatically.</p><div class="btnrow">${button('brex-link','Attach payments',true)}</div><hr><label for="brex-title">New contract title</label><input id="brex-title" maxlength="200" value="${esc(g.merchant)}"><div class="btnrow">${button('brex-create','Create draft and complete details')}${button('brex-ignore','Ignore this group')}${button('brex-reopen','Reopen review')}</div><div id="brex-complete"></div><hr><h3>Selected payments</h3><p>Only the selected payments change. Different purchases from the same vendor can belong to different contracts. Individual assignment disables the group’s automatic rule; future payments need review.</p><div class="btnrow">${button('brex-link-selected','Attach selected payments',true)}${button('brex-create-selected','Create draft for selected payments')}${button('brex-ignore-selected','Ignore selected payments')}${button('brex-reopen-selected','Reopen selected payments')}</div></section></div><section class="scard"><h3>Assignment history</h3><p>This section shows historical group decisions. Individual decisions appear beside each payment. Existing individual assignments cannot be overwritten by a group action.</p>${(d.decisions||[]).slice(0,20).map(e=>`<p>${esc(when(e.at))} · ${e.automatic?'Automatic import':esc(e.person)} · ${labels[variant(e.before)]} → ${labels[variant(e.after)]}${variant(e.after)==='linked'?' · Contract '+e.after.linked:''}</p>`).join('')||'<p>No decisions yet.</p>'}</section>`;
  root.querySelector('#brex-analyze').disabled=!status.aiEnabled;
  const candidates=new Set(g.candidates.map(String));let selectedContract=null,searchVersion=0;
  function drawContracts(){const q=root.querySelector('#brex-target-search').value.toLowerCase();root.querySelector('#brex-target').innerHTML='<option value="">Choose a contract</option>'+d.contracts.filter(c=>!['ended','archived'].includes(c.status)&&`${c.title} ${c.vendor}`.toLowerCase().includes(q)).sort((a,b)=>Number(candidates.has(String(b.id)))-Number(candidates.has(String(a.id)))).map(c=>`<option value="${c.id}">${candidates.has(String(c.id))?'Suggested: ':''}${esc(c.title)} · ${esc(c.vendor)}</option>`).join('');}
  drawContracts();root.querySelector('#brex-target-search').oninput=async e=>{const seq=++searchVersion;try{const found=await api.findBrexContracts(token,e.target.value);if(!current()||seq!==searchVersion)return;d.contracts=found;drawContracts();root.querySelector('#brex-existing').innerHTML='';}catch{if(current())message('Contract search is unavailable. Try again.',true);}};
  root.querySelector('#brex-target').onchange=e=>{selectedContract=d.contracts.find(c=>String(c.id)===e.target.value);const c=selectedContract;root.querySelector('#brex-existing').innerHTML=c?`<p><strong>${esc(c.title)}</strong> · ${esc(c.status)}</p><dl class="brex-facts">${c.fields.filter(f=>['interval','amountMinor','currency','renewalDate','noticeDays','noticeMonths'].includes(f.name)).map(f=>`<dt>${fieldLabels[f.name]}</dt><dd>${esc(f.value||'Not recorded')}</dd>`).join('')}</dl><p>Attach adds this payment evidence. To fill missing fields or change existing terms, use the guided review after attaching.</p>`:'';};
  if(linked!=null){root.querySelector('#brex-complete').innerHTML=`<a class="pill primary" href="#/payments/guide/${linked}">Complete or review contract details</a>`;}
  const chosen=new Set();let reviews=new Map((d.reviews||[]).map(r=>[r.id,r]));
  if(g.summary?.split){for(const key of ['brex-link','brex-create','brex-ignore','brex-reopen','brex-auto'])root.querySelector('#'+key).disabled=true;}
  let paymentOffset=d.next,payments=d.payments;
  function drawPayments(){root.querySelector('#brex-evidence').innerHTML=`<table class="saas-table"><thead><tr><th>Select</th><th>Date</th><th>Type</th><th>Booked amount</th><th>Description</th><th>Assignment</th></tr></thead><tbody>${payments.map(p=>{const review=reviews.get(p.id),assigned=review?.assignment?.state||g.state,target=assigned.linked;return `<tr><td><input type="checkbox" data-payment="${esc(p.id)}" aria-label="Select payment ${esc(p.id)}" ${chosen.has(p.id)?'checked':''}></td><td>${esc(p.date)}</td><td>${esc(p.kind)}</td><td>${esc(paymentMoney(p.amountMinor,p.currency))}</td><td>${esc(p.description)}</td><td>${target!=null?`<a href="#/payments/guide/${target}">${esc(d.contracts.find(c=>c.id===target)?.title||'Contract '+target)}</a>`:labels[variant(assigned)]}${review?.history?.length?`<details><summary>Assignment history</summary>${review.history.map(e=>`<p>${esc(when(e.at))} · ${esc(e.person)} · ${labels[variant(e.before)]} → ${labels[variant(e.after)]}${e.after.linked!=null?' · Contract '+e.after.linked:''}</p>`).join('')}</details>`:''}</td></tr>`;}).join('')}</tbody></table>`;root.querySelector('#brex-more-payments').hidden=!paymentOffset.length;
   root.querySelectorAll('[data-payment]').forEach(box=>box.onchange=()=>{if(box.checked&&chosen.size>=50){box.checked=false;message('Select at most 50 payments at a time.',true);return;}if(box.checked)chosen.add(box.dataset.payment);else chosen.delete(box.dataset.payment);root.querySelector('#brex-selected').textContent=`${chosen.size} payments selected`;});
  }
  drawPayments();run(root.querySelector('#brex-more-payments'),async()=>{const more=opt(await api.brexReviewDetail(token,gid,paymentOffset[0]));if(current()&&more){if(more.group.revision!==g.revision){message('Payments changed. Reload before assigning.',true);return;}payments.push(...more.payments);for(const r of more.reviews||[])reviews.set(r.id,r);paymentOffset=more.next;drawPayments();}});
  const decideSelected=async decision=>{if(!chosen.size){message('Select at least one payment.',true);return;}const r=await api.decideBrexPayments(token,gid,g.revision,[...chosen],decision);if(!current())return;if(r.ok){await reload();}message(r.detail,!r.ok);};
  run(root.querySelector('#brex-link-selected'),async()=>{const value=root.querySelector('#brex-target').value;if(!value){message('Choose a contract first.',true);return;}await decideSelected({link:BigInt(value)});});
  run(root.querySelector('#brex-create-selected'),()=>decideSelected({create:root.querySelector('#brex-title').value.trim()}));
  run(root.querySelector('#brex-ignore-selected'),()=>decideSelected({dismiss:null}));run(root.querySelector('#brex-reopen-selected'),()=>decideSelected({reopen:null}));
  const decide=async decision=>{const r=await api.decideBrex(token,gid,g.revision,decision,root.querySelector('#brex-auto').checked,{[root.querySelector('#brex-kind').value]:null});if(!current())return;if(r.ok){if(opt(r.contractId)!=null)location.hash=`#/payments/guide/${r.contractId[0]}`;else await reload();}message(r.detail,!r.ok);};
  run(root.querySelector('#brex-link'),async()=>{const value=root.querySelector('#brex-target').value;if(!value){message('Choose a contract first.',true);return;}await decide({link:BigInt(value)});});
  run(root.querySelector('#brex-create'),()=>decide({create:root.querySelector('#brex-title').value.trim()}));
  run(root.querySelector('#brex-ignore'),()=>decide({dismiss:null}));run(root.querySelector('#brex-reopen'),()=>decide({reopen:null}));
  run(root.querySelector('#brex-analyze'),async()=>{message('Reviewing merchant and payment evidence…');const r=await api.analyzeBrexReview(token,gid);if(current()){if(r.ok)await reload();message(r.detail,!r.ok);}});
 }
 async function guide(cid){
  const skipped=new Set();let data,conversation=[],selected='',drawVersion=0;
  async function loadGuide(){const d=opt(await api.brexGuide(token,cid));if(!current())return false;if(!d){root.innerHTML='<p role="alert">Contract unavailable in this space.</p>';return false;}data=d;return true;}
  if(!await loadGuide())return;
  function draw(){const version=++drawVersion;const c=data.contract;const fields=Object.fromEntries(c.fields.map(f=>[f.name,f.value]));
   const candidates=Object.keys(questions).filter(f=>!['title','vendor','end','note'].includes(f)&&(!fields[f]||fields[f]==='unknown')&&!skipped.has(f)&&!(fields.interval==='once'&&['renewalDate','noticeDays','noticeMonths'].includes(f))&&!(f==='noticeDays'&&fields.noticeMonths)&&!(f==='noticeMonths'&&fields.noticeDays));
   const name=selected||candidates[0];
   root.innerHTML=heading('Complete contract details',esc(c.title)+' · Answer one question at a time. Unknown values can stay unknown.')+`<p><a href="#/payments">← Payment review</a> · <a href="#/c/${c.id}">Open contract</a></p><section class="scard brex-chat"><div class="brex-conversation" role="log" aria-label="Contract conversation">${conversation.map(m=>`<p class="${m.who==='you'?'brex-user':'brex-assistant'}"><strong>${m.who==='you'?'You':'Contracts'}</strong><br>${esc(m.text)}</p>`).join('')}<p class="brex-assistant"><strong>Contracts</strong><br>${name?esc(questions[name]):'The remaining questions are complete or skipped. You can review any field below. A new contract stays a draft until you activate tracking in its contract view.'}</p></div><label for="brex-guide-field">Complete or change a field</label><select id="brex-guide-field"><option value="">Next missing detail</option>${Object.entries(fieldLabels).map(([k,v])=>`<option value="${k}" ${name===k?'selected':''}>${v}${fields[k]?' · '+esc(fields[k]):' · missing'}</option>`).join('')}</select>${name?`<p>Current value: <strong>${esc(fields[name]||'Not recorded')}</strong></p><form id="brex-answer-form"><label for="brex-answer">Your answer</label><textarea id="brex-answer" maxlength="2000" rows="3" required aria-describedby="brex-answer-help"></textarea><p id="brex-answer-help" class="spacehelp">${name==='amountMinor'?'Explicit value: minor units (1990 = 19.90 for CHF/EUR/USD). With AI, you can write “19.90 CHF per month”. Only this field will be proposed.':'Use an explicit value, or let the configured AI interpret your answer. Dates use YYYY-MM-DD.'}</p><div class="btnrow">${(choices[name]||[]).map(([v,l])=>`<button type="button" class="pill outline" data-answer="${v}">${l}</button>`).join('')}</div><label class="brex-check"><input id="brex-answer-ai" type="checkbox">Interpret my answer with Hub AI</label><p class="spacehelp">Only your answer, field name and recorded currency are sent. The AI proposes a value; you confirm it.</p><div class="btnrow"><button class="pill primary" type="submit">Preview answer</button>${button('brex-skip','Skip for now')}</div></form><div id="brex-answer-preview" aria-live="polite"></div>`:''}</section>`;
   root.querySelector('#brex-guide-field').onchange=e=>{selected=e.target.value;draw();};
   if(!name)return;
   root.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{root.querySelector('#brex-answer').value=b.dataset.answer;root.querySelector('#brex-answer-ai').checked=false;});
   run(root.querySelector('#brex-skip'),async()=>{skipped.add(name);conversation.push({who:'you',text:'Skip '+fieldLabels[name]+' for now.'});selected='';draw();});
   let submitting=false;
   root.querySelector('#brex-answer-form').onsubmit=async e=>{e.preventDefault();if(submitting||!current())return;submitting=true;const submit=e.target.querySelector('[type=submit]');submit.disabled=true;const answer=root.querySelector('#brex-answer').value;try{
    const r=await api.answerBrexGuide(token,cid,c.revision,name,answer,root.querySelector('#brex-answer-ai').checked);if(!current()||version!==drawVersion)return;
    if(!r.ok){message(r.detail,true);return;}
    const replacing=!!r.before&&r.before!=='unknown';root.querySelector('#brex-answer-preview').innerHTML=`<section class="brex-preview"><h3>Review before saving</h3><p>${fieldLabels[name]}: <del>${esc(r.before||'Not recorded')}</del> → <strong>${esc(r.value||'Empty')}</strong></p><p>${replacing?'This replaces a confirmed value. Other contract fields are retained.':'This fills the missing detail.'}${['noticeDays','noticeMonths'].includes(name)?' The alternative notice unit is cleared and cancellation/decision dates are recalculated.':''}${['end','renewalDate','renewalRule','start'].includes(name)?' Derived cancellation/decision dates may be recalculated.':''}</p>${button('brex-apply',replacing?'Replace confirmed value':'Add confirmed detail',true)}</section>`;
    run(root.querySelector('#brex-apply'),async()=>{const saved=await api.applyBrexGuide(token,cid,r.revision,name,r.value,replacing);if(!current()||version!==drawVersion)return;if(!saved.ok){message(saved.detail,true);return;}conversation.push({who:'you',text:answer},{who:'assistant',text:fieldLabels[name]+': '+r.value+' — saved.'});selected='';if(await loadGuide())draw();});
   }catch{if(current())message('Could not interpret the answer. Your text is retained; try again.',true);}finally{submitting=false;if(current())submit.disabled=false;}};
  }
  draw();
 }
}
